def transform(grid):
    h, w = len(grid), len(grid[0])
    directions = [
        (lambda r, c: r),       # horizontal stripes
        (lambda r, c: c),       # vertical stripes
        (lambda r, c: c - r),   # down-right diagonals
        (lambda r, c: r + c),   # down-left diagonals
    ]

    best_groups = None
    best_score = -1

    for key_fn in directions:
        groups = {}
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color:
                    groups.setdefault(key_fn(r, c), []).append(color)

        score = sum(len(vals) for vals in groups.values()
                    if len(vals) >= 2 and len(set(vals)) == 1)
        if score > best_score:
            best_score = score
            best_groups = groups
            best_key_fn = key_fn

    # Keep only stripe coordinates whose observed cells agree in color.
    stripes = {k: vals[0] for k, vals in best_groups.items()
               if len(set(vals)) == 1}

    period = 1
    for p in range(1, max(h, w) + 1):
        phases = {}
        valid = True
        for k, color in stripes.items():
            phase = k % p
            if phase in phases and phases[phase] != color:
                valid = False
                break
            phases[phase] = color
        if valid:
            period = p
            break

    phases = {}
    for k, color in stripes.items():
        phases[k % period] = color

    # Use the most frequent observed color for any unspecified phase.
    counts = {}
    last_color = 0
    for row in grid:
        for color in row:
            if color:
                counts[color] = counts.get(color, 0) + 1
                last_color = color
    default = last_color
    if counts:
        highest = max(counts.values())
        default = next(color for row in reversed(grid) for color in reversed(row)
                       if color and counts[color] == highest)

    out = []
    for r in range(h):
        row = []
        for c in range(w):
            k = best_key_fn(r, c)
            row.append(phases.get(k % period, default))
        out.append(row)
    return out
